/// Determines if the given string is a palindrome, ignoring case and non-alphanumeric characters.
///
/// # Examples
///
/// ```
/// assert_eq!(is_palindrome("A man, a plan, a canal: Panama"), true);
/// assert_eq!(is_palindrome("No 'x' in Nixon"), true);
/// assert_eq!(is_palindrome("Hello, World!"), false);
/// assert_eq!(is_palindrome(""), true);
/// ```
fn is_palindrome(s: &str) -> bool {
    let filtered_chars: Vec<char> = s.chars()
        .filter(|c| c.is_alphanumeric())
        .map(|c| c.to_ascii_lowercase())
        .collect();

    filtered_chars == filtered_chars.iter().rev().cloned().collect()
}

// Check function to verify the correctness of the generated function.
fn check() {
    assert_eq!(is_palindrome("A man, a plan, a canal: Panama"), true);
    assert_eq!(is_palindrome("No 'x' in Nixon"), true);
    assert_eq!(is_palindrome("Hello, World!"), false);
    assert_eq!(is_palindrome(""), true);
    println!("All tests passed!");
}

