/// Run-length encodes the input string.
///
/// # Examples
///
/// ```
/// assert_eq!(rle("aaabcc"), "3a1b2c");
/// assert_eq!(rle(""), "");
/// ```
pub fn rle(input: &str) -> String {
    input.chars()
        .fold(String::new(), |mut encoded, current| {
            let count = input.chars()
                .take_while(|&next| next == current)
                .count();
            encoded.push_str(&format!("{}{}", count, current));
            encoded
        })
}

