/// Calculates the greatest common divisor of two non-negative integers.
///
/// # Examples
///
/// ```
/// assert_eq!(gcd(0, 10), 10);
/// assert_eq!(gcd(10, 0), 10);
/// assert_eq!(gcd(48, 18), 6);
/// ```
pub fn gcd(a: u64, b: u64) -> u64 {
    if b == 0 {
        a
    } else {
        gcd(b, a % b)
    }
}

