/// Reverses the order of words in a given string.
///
/// # Examples
///
/// ```
/// assert_eq!(reverse_words("Hello world"), "world Hello");
/// assert_eq!(reverse_words("  Leading spaces"), "spaces Leading");
/// assert_eq!(reverse_words("Trailing spaces  "), "Trailing spaces ");
/// assert_eq!(reverse_words("  Multiple   spaces  "), "spaces   Multiple  ");
/// ```
fn reverse_words(s: &str) -> String {
    s.split_whitespace()
        .rev()
        .collect::<Vec<&str>>()
        .join(" ")
}

