    let a_chars: Vec<char> = a.chars().filter(|&c| !c.is_whitespace()).collect();
    let b_chars: Vec<char> = b.chars().filter(|&c| !c.is_whitespace()).collect();

    a_chars.iter().all(|&c| b_chars.iter().filter(|&b| b == c).count() == 1)
}

