/// Computes the factorial of a non-negative integer n.
/// If the result does not fit in a u64, returns None.
///
/// # Examples
///
/// ```
/// assert_eq!(factorial(5), Some(120));
/// assert_eq!(factorial(0), Some(1));
/// assert_eq!(factorial(10), Some(3628800));
/// assert_eq!(factorial(20), Some(2432902008176640000));
/// assert_eq!(factorial(21), None); // 21! overflows a u64
/// ```
pub fn factorial(n: u32) -> Option<u64> {
    if n == 0 || n == 1 {
        return Some(1);
    }

    let mut result = 1;
    for i in 2..=n {
        if result > u64::MAX / i {
            return None;
        }
        result *= i;
    }

    Some(result)
}

// A simple check function to verify the correctness of the factorial function.
fn check_factorial() {
    assert_eq!(factorial(5), Some(120));
    assert_eq!(factorial(0), Some(1));
    assert_eq!(factorial(10), Some(3628800));
    assert_eq!(factorial(20), Some(2432902008176640000));
    assert_eq!(factorial(21), None); // 21! overflows a u64
    println!("All tests passed!");
}

