/// Returns the largest sum of a contiguous, non-empty run of elements.
///
/// # Examples
///
/// ```
/// assert_eq!(max_subarray(&[]), 0);
/// assert_eq!(max_subarray(&[1, 2, 3]), 6);
/// assert_eq!(max_subarray(&[-1, -2, -3]), -6);
/// assert_eq!(max_subarray(&[1, -2, 3, -4, 5]), 6);
/// ```
pub fn max_subarray(v: &[i64]) -> i64 {
    if v.is_empty() {
        return 0;
    }

    let mut max_sum = v[0];
    let mut current_sum = v[0];

    for &num in &v[1..] {
        current_sum = num.max(current_sum + num);
        max_sum = max_sum.max(current_sum);
    }

    max_sum
}

