pub fn from_roman(s: &str) -> Option<u32> {
    let mut number = 0;

    for (i, c) in s.chars().enumerate() {
        let value = match c {
            'I' => 1,
            'V' => 5,
            'X' => 10,
            'L' => 50,
            'C' => 100,
            'D' => 500,
            'M' => 1000,
            _ => return None,
        };

        if i > 0 && value > number {
            number -= value;
        } else {
            number += value;
        }
    }

    Some(number)
}

