/// Encrypts a string using the Caesar cipher.
///
/// # Examples
///
/// ```
/// assert_eq!(caesar("abc", 3), "def");
/// assert_eq!(caesar("xyz", 2), "abc");
/// assert_eq!(caesar("Hello, World!", 5), "Mjqqt, Btwqi!");
/// assert_eq!(caesar("Rust", 10), "Vqrs");
/// ```
fn caesar(s: &str, shift: u8) -> String {
    s.chars()
        .map(|c| {
            if c.is_ascii_alphabetic() {
                let base = if c.is_ascii_uppercase() { 'A' } else { 'a' };
                ((c as u8 - base + shift) % 26) as u8 + base
            } else {
                c
            }
        })
        .collect()
}

