/// Removes consecutive repeated values from a slice, keeping the first of each run.
///
/// # Examples
///
/// ```
/// assert_eq!(dedup(&[1, 2, 2, 3, 4, 4, 4]), vec![1, 2, 3, 4]);
/// assert_eq!(dedup(&[1, 1, 1, 1]), vec![1]);
/// assert_eq!(dedup(&[]), Vec::<i32>::new());
/// ```
pub fn dedup(v: &[i32]) -> Vec<i32> {
    v.iter()
        .enumerate()
        .filter_map(|(i, &x)| if i == 0 || x != v[i - 1] { Some(x) } else { None })
        .collect()
}

