pub fn is_balanced(s: &str) -> bool {
    let mut stack = Vec::new();

    for c in s.chars() {
        match c {
            '(' | '[' | '{' => stack.push(c),
            ')' => {
                if stack.pop().is_none() || stack.last() != Some('(')) {
                    return false;
                }
            },
            ']' => {
                if stack.pop().is_none() || stack.last() != Some('[')) {
                    return false;
                }
            },
            '}' => {
                if stack.pop().is_none() || stack.last() != Some('{')) {
                    return false;
                }
            },
            _ => {}
        }
    }

    stack.is_empty()
}

