/// Calculates the median of a slice of f64 values.
/// If the slice is empty, returns None.
/// The slice is not sorted.
///
/// # Examples
///
/// ```
/// assert_eq!(median(&[]), None);
/// assert_eq!(median(&[1.0]), Some(1.0));
/// assert_eq!(median(&[3.0, 1.0, 2.0]), Some(2.0));
/// assert_eq!(median(&[5.0, 3.0, 1.0, 4.0, 2.0]), Some(3.0));
/// ```
pub fn median(v: &[f64]) -> Option<f64> {
    if v.is_empty() {
        return None;
    }

    let mut sorted_v = v.to_vec();
    sorted_v.sort_unstable();

    let len = sorted_v.len();
    if len % 2 == 0 {
        Some((sorted_v[len / 2 - 1] + sorted_v[len / 2]) / 2.0)
    } else {
        Some(sorted_v[len / 2])
    }
}

// Check function to verify the correctness of the median function
fn check() {
    assert_eq!(median(&[]), None);
    assert_eq!(median(&[1.0]), Some(1.0));
    assert_eq!(median(&[3.0, 1.0, 2.0]), Some(2.0));
    assert_eq!(median(&[5.0, 3.0, 1.0, 4.0, 2.0]), Some(3.0));
    println!("All tests passed!");
}

