/// Parses a colour written as "#rrggbb" (hexadecimal, any case).
/// Returns None for anything else.
///
/// # Examples
/// ```
/// assert_eq!(hex_to_rgb("#000000"), Some((0, 0, 0)));
/// assert_eq!(hex_to_rgb("#FFFFFF"), Some((255, 255, 255)));
/// assert_eq!(hex_to_rgb("#123456"), Some((18, 52, 86)));
/// assert_eq!(hex_to_rgb("#GRR"), None);
/// ```
pub fn hex_to_rgb(s: &str) -> Option<(u8, u8, u8)> {
    if s.len() != 7 || !s.chars().all(|c| c.is_digit(16)) {
        return None;
    }

    let mut rgb = [0; 3];
    for (i, c) in s.chars().enumerate() {
        if i % 2 == 0 {
            rgb[i / 2] = c.to_digit(16).unwrap() as u8 * 16;
        } else {
            rgb[i / 2] += c.to_digit(16).unwrap();
        }
    }

    Some(rgb)
}

