use std::collections::HashMap;

/// Parses a string into a HashMap of key-value pairs.
///
/// # Examples
///
/// ```
/// assert_eq!(parse_kv("a=1;b=two"), HashMap::from([("a".to_string(), "1".to_string()), ("b".to_string(), "two".to_string())]));
/// assert_eq!(parse_kv("a;b=two"), HashMap::from([("a".to_string(), "".to_string()), ("b".to_string(), "two".to_string())]));
/// assert_eq!(parse_kv("a=b"), HashMap::from([("a".to_string(), "b".to_string())]));
/// assert_eq!(parse_kv("a"), HashMap::from([("a".to_string(), "".to_string())]));
/// ```
pub fn parse_kv(s: &str) -> HashMap<String, String> {
    s.split(';')
        .filter_map(|pair| {
            let mut parts = pair.split('=');
            let key = parts.next().map(|s| s.to_string());
            let value = parts.next().map(|s| s.to_string());
            key.and_then(|k| value.map(|v| (k, v)))
        })
        .collect()
}

