    let mut pixels = PIXELS.lock().unwrap();
    for y in 0..height {
        for x in 0..width {
            let i = (y * width + x) * 4;
            pixels[i] = (t_ms % 256) as u8;
            pixels[i + 1] = (t_ms % 256) as u8;
            pixels[i + 2] = (t_ms % 256) as u8;
            pixels[i + 3] = 255;
        }
    }
    pixels.as_ptr()
}
